-- Maze Quest: race a friend online with a 6-character room code, and lantern questions that match the player's grade (K to 5th).
-- Run once in the Supabase SQL Editor (safe to run again).
update games set data = data || $j${"summary": "Race a friend through 8 forest mazes, K to 5th grade.", "players": "1, or 2 online (share a code)", "rules": ["Pick your explorer from 8 characters, and pick your grade, from Kindergarten to 5th: the lantern questions match it.", "Arrow keys or W, A, S, D walk your explorer. The on-screen buttons work too.", "Keep walking the same way and you speed up.", "Start at the camp tent and find your way to the cabin.", "Walk up to a glowing lantern to pause the clock for a quick math or spelling question.", "Answer right and you jump ten squares along the real path.", "Stuck? Press Hint for an arrow pointing the right way.", "Finish all eight forests to see your time for each one on the leaderboard.", "Race a friend online: make a room and share the 6-character code, or type the code your friend gave you.", "You both walk the same forest on your own screens. Your friend's explorer is the see-through one.", "Wait for 3, 2, 1, GO! The first to reach the cabin wins that forest.", "In a race the clock keeps going while you answer a lantern, so you choose: answer for a jump, or keep walking.", "Either player can press Next forest. After Wizard's Wood, see who won the most forests.", "Sound is on: press the speaker button to turn it off."]}$j$::jsonb, updated_at = now()
where id = 'game-maze';
